reflectionsUI <- function(id) {
 ns<-NS(id)
 tagList(tags$div(class='experience-heading',tags$p(class='eyebrow','REFLECT'),tags$h1('Learn the shape of your time.'),tags$p(class='lead','Notice what helps. Keep room for what matters.')),
 tabsetPanel(id=ns('section'),type='pills',
  tabPanel('Overview',insightsUI('insights')),
  tabPanel('Weekly',dateInput(ns('week'),'Week beginning',week_start()),tags$div(class='card-actions',actionButton(ns('previous'),'Previous week',class='btn-quiet'),actionButton(ns('current'),'Current week',class='btn-quiet'),actionButton(ns('next_week'),'Next week',class='btn-quiet')),uiOutput(ns('capacity_week')),
   section('Your work roles, side by side',uiOutput(ns('role_cards')),tableOutput(ns('weekly_table')),tags$p(class='hint','Actual effort = logged task time plus confirmed meeting attendance, excluding known overlaps. Scheduled meetings are shown separately. A saved weekly review freezes that week’s target, pay model and reference rate. Historical weeks without a review use current role settings. Gross extra is an estimate from recorded work/items and completed bonuses, not a payment receipt.')),
   section('Close the week on your terms',selectInput(ns('role'),'Work role',NULL),checkboxInput(ns('complete'),'I finished all necessary tasks for this role this week',FALSE),textAreaInput(ns('role_note'),'A note for this role',rows=2),actionButton(ns('review_save'),'Save weekly role review',class='btn-primary'),tags$p(class='hint','For fixed salary, fewer hours count as saved only after this check. Saving or overrunning hours × the role’s reference hourly rate gives the value of time, not extra salary earned. Uncheck and save if more necessary work remains.')),
   section('Which meetings actually happened?',checkboxGroupInput(ns('meetings'),'Select meetings attended this week',NULL),actionButton(ns('meetings_save'),'Save attendance',class='btn-quiet'),tags$p(class='hint','Scheduled meetings block the calendar immediately. Confirm attendance to include them in actual hours and the recorded timesheet. Past attendance remains a dated record if you later edit a recurring commitment.')),
   textAreaInput(ns('week_note'),'Weekly reflection: what helped, what needs less?',rows=3),actionButton(ns('week_note_save'),'Save weekly reflection',class='btn-quiet')),
  tabPanel('Monthly',fluidRow(column(6,numericInput(ns('year'),'Year',as.integer(format(Sys.Date(),'%Y')),min=2000,max=2200,step=1)),column(6,selectInput(ns('month'),'Month',setNames(1:12,month.name),as.integer(format(Sys.Date(),'%m'))))),
   section('The year at a glance',tableOutput(ns('year_table'))),uiOutput(ns('capacity_month')),
   section('This month, by work role',tableOutput(ns('month_roles'))),section('Weekly time balance across your roles',uiOutput(ns('week_matrix')),tags$p(class='hint','Saved hours require a completed weekly review. Negative hours mean overwork in a fixed salary role. Values use the snapshotted rate when reviewed; unrevised historical weeks use current contract references.')),
   textAreaInput(ns('month_note'),'Monthly reflection',rows=3),actionButton(ns('month_note_save'),'Save monthly reflection',class='btn-quiet'),
   section('Timesheets & working-window review',tags$p('The recorded CSV preserves the dates and times you entered. Entries outside your chosen working window, overlaps, unknown clock times and unconfirmed meetings are flagged for review.'),
    fluidRow(column(6,numericInput(ns('window_start'),'Working day begins',7,min=0,max=23.75,step=.25)),column(6,numericInput(ns('window_end'),'Working day ends',17,min=.25,max=24,step=.25))),
    fluidRow(column(6,numericInput(ns('lunch_start'),'Lunch begins',12,min=0,max=23.75,step=.25)),column(6,numericInput(ns('lunch_end'),'Lunch ends',13,min=.25,max=24,step=.25))),actionButton(ns('window_save'),'Save export preferences',class='btn-quiet'),selectInput(ns('timesheet_role'),'Work role to export',NULL),
    downloadButton(ns('actual_csv'),'Download recorded timesheet (.csv)'),downloadButton(ns('draft_csv'),'Download working-window planning draft (.csv)'),
    tags$p(class='hint','The separate planning draft allocates the same recorded durations into weekdays inside your chosen window, leaves lunch free, retains fitting entries first and lists any hours that do not fit. Every allocation links to its original entry/date. It is a hypothetical schedule, not an attendance record or certification of legal compliance.'),tableOutput(ns('timesheet'))))),
 section('Keep a little room in reserve',numericInput(ns('reserve'),'Time reserve (%)',20,min=0,max=70,step=5),actionButton(ns('reserve_save'),'Save time reserve',class='btn-quiet'),tags$p(class='hint','Default 20%. Free capacity excludes elapsed time, commitments, the daily focus limit, this reserve, draft task blocks and unfinished flexible chores. Role cards also show room inside each role’s commitment. This reflection reserve does not change the planner’s separate buffer.')))
}
reflectionsServer <- function(id,state,commit,controls)moduleServer(id,function(input,output,session){
 today<-controls$today;week<-reactive(week_start(input$week %||% today()));month<-reactive(as.Date(sprintf('%04d-%02d-01',as.integer(input$year %||% format(today(),'%Y')),as.integer(input$month %||% format(today(),'%m')))));month_end<-reactive(seq(month(),by='month',length.out=2)[2]-1)
 # Lifecycle callbacks run outside reactive consumers in a live Shiny session.
 # Take one isolated date snapshot; testServer's ambient context can hide this bug.
 session$onFlushed(function(){
  current_day<-isolate(today())
  updateDateInput(session,'week',value=week_start(current_day))
  updateNumericInput(session,'year',value=as.integer(format(current_day,'%Y')))
  updateSelectInput(session,'month',selected=as.integer(format(current_day,'%m')))
 },once=TRUE)
 observeEvent(input$previous,updateDateInput(session,'week',value=week()-7));observeEvent(input$next_week,updateDateInput(session,'week',value=week()+7));observeEvent(input$current,updateDateInput(session,'week',value=week_start(today())))
 observe({s<-state();updateSelectInput(session,'role',choices=choices_id(s$jobs,'name'),selected=isolate(input$role));updateSelectInput(session,'timesheet_role',choices=c('All roles'='',choices_id(all_records(s,'jobs'),'name')),selected=isolate(input$timesheet_role))})
 session$onFlushed(function(){st<-isolate(state())$settings;for(n in c('reserve','window_start','window_end','lunch_start','lunch_end'))updateNumericInput(session,n,value=st[[switch(n,reserve='reserve_pct',window_start='timesheet_start',window_end='timesheet_end',lunch_start='timesheet_lunch_start',lunch_end='timesheet_lunch_end')]])},once=TRUE)
 observeEvent(input$reserve_save,{s<-state();s$settings$reserve_pct<-input$reserve;commit_safely(commit,s)})
 observeEvent(input$window_save,{s<-state();for(n in c('window_start','window_end','lunch_start','lunch_end'))s$settings[[switch(n,window_start='timesheet_start',window_end='timesheet_end',lunch_start='timesheet_lunch_start',lunch_end='timesheet_lunch_end')]]<-input[[n]];commit_safely(commit,s)})
 weekly<-reactive(role_week_report(state(),week()))
 week_plan<-reactive(plan_work(state(),controls$strategy(),week(),controls$protect(),controls$buffer(),controls$cap(),controls$seed(),today()))
 role_room<-function(r){p<-week_plan()$plan;vapply(seq_len(nrow(r)),function(i)max(0,r$Target_h[i]*(1-state()$settings$reserve_pct/100)-r$Actual_h[i]-sum(p$hours[p$job_id==r$Job_id[i]])-max(0,r$Scheduled_meeting_h[i]-r$Confirmed_meeting_h[i])),numeric(1))}
 output$role_cards<-renderUI({req(identical(input$section,'Weekly'));r<-weekly();if(!nrow(r))return(tags$p(class='empty-hint','Add a work role to begin.'));room<-role_room(r)
  tags$div(class='role-comparison',lapply(seq_len(nrow(r)),function(i){fixed<-r$Pay[i]=='Salary';status<-if(fixed&&r$Over_h[i]>0)'negative'else if(fixed&&r$Saved_h[i]>0)'positive'else'neutral';tags$article(class=paste('role-week-card',status),tags$p(class='eyebrow',r$Role[i]),tags$h3(paste(round(r$Actual_h[i],2),'/',round(r$Target_h[i],2),'h')),tags$p(if(fixed&&r$Over_h[i]>0)paste('Overwork:',round(r$Over_h[i],2),'h')else if(fixed&&r$Complete[i])paste('Saved:',round(r$Saved_h[i],2),'h')else paste('Still to commitment:',round(r$Still_needed_h[i],2),'h')),
   if(fixed)tags$p(paste('Time value:',round(r$Time_value[i],2),state()$settings$currency))else tags$p(paste(round(r$Units[i],2),'items · estimated gross extra',round(r$Gross_extra[i],2),state()$settings$currency)),tags$small(paste('Room within role after reserve and plan:',round(room[i],2),'h')),if(r$Unknown_item_sessions[i]>0)tags$p(class='hint','Some older sessions have no item count.'))}))
 })
 output$weekly_table<-renderTable({req(identical(input$section,'Weekly'));r<-weekly();if(!nrow(r))return(NULL);r$Room_after_reserve_h<-role_room(r);r[,c('Role','Pay','Target_h','Logged_h','Confirmed_meeting_h','Scheduled_meeting_h','Actual_h','Still_needed_h','Saved_h','Over_h','Time_value','Units','Gross_extra','Room_after_reserve_h')]},digits=2,striped=TRUE)
 cap_ui<-function(from,to){c<-period_capacity(state(),from,to,today());tags$div(class='metric-grid',metric('Available after reserve',paste0(round(c$capacity,1),' h')),metric('Draft task blocks',paste0(round(c$planned,1),' h')),metric('Flexible chores allowance',paste0(round(c$chores,1),' h')),metric('Still free',paste0(round(c$free,1),' h'),if(c$over>0)paste(round(c$over,1),'h exceed remaining capacity')else'Space you can choose to keep open'))}
 output$capacity_week<-renderUI({req(identical(input$section,'Weekly'));cap_ui(week(),week()+6)});output$capacity_month<-renderUI({req(identical(input$section,'Monthly'));cap_ui(month(),month_end())})
 observe({s<-state();r<-s$role_reviews[s$role_reviews$job_id==(input$role %||% '')&s$role_reviews$week==as.character(week()),,drop=FALSE];updateCheckboxInput(session,'complete',value=nrow(r)==1&&r$complete);updateTextAreaInput(session,'role_note',value=if(nrow(r))r$note else '')})
 observeEvent(input$review_save,{tryCatch(commit(save_role_review(state(),input$role,week(),isTRUE(input$complete),input$role_note %||% '')),error=notify_error)})
 meeting_choices<-reactive({s<-state();p<-commitment_events(s,week(),week()+6,'Meeting');a<-s$attendance[s$attendance$date>=as.character(week())&s$attendance$date<=as.character(week()+6),,drop=FALSE];for(i in seq_len(nrow(a)))if(!a$id[i]%in%p$id)p<-rbind(p,data.frame(id=a$id[i],source_id=a$source_id[i],date=a$date[i],title=a$title[i],kind='Meeting',job_id=a$job_id[i],start=a$start[i],end=a$end[i]));p})
 observe({p<-meeting_choices();updateCheckboxGroupInput(session,'meetings',choices=if(nrow(p))setNames(p$id,paste(p$date,p$title,fmt_hour(p$start),'–',fmt_hour(p$end)))else character(),selected=intersect(p$id,state()$attendance$id))})
 observeEvent(input$meetings_save,{s<-state();p<-meeting_choices();ids<-input$meetings %||% character();p<-p[p$id%in%ids,,drop=FALSE];old<-s$attendance[s$attendance$date<as.character(week())|s$attendance$date>as.character(week()+6),,drop=FALSE];s$attendance<-rbind(old,p[,names(s$attendance),drop=FALSE]);commit_safely(commit,s)})
 observe({s<-state();for(period in c('Weekly','Monthly')){d<-as.character(if(period=='Weekly')week()else month());r<-s$reflections[s$reflections$period==period&s$reflections$date==d,,drop=FALSE];updateTextAreaInput(session,if(period=='Weekly')'week_note'else'month_note',value=if(nrow(r))r$note else '')}})
 save_note<-function(period,date,note){s<-state();d<-as.character(date);r<-s$reflections;s$reflections<-rbind(r[!(r$period==period&r$date==d),,drop=FALSE],data.frame(period=period,date=d,note=note %||% ''));commit_safely(commit,s)}
 observeEvent(input$week_note_save,save_note('Weekly',week(),input$week_note));observeEvent(input$month_note_save,save_note('Monthly',month(),input$month_note))
 monthly_rows<-function(from,to){out<-data.frame();for(ws in as.character(seq(week_start(from),week_start(to),by='7 days')))out<-rbind(out,role_week_report(state(),as.Date(ws),from,to));out}
 monthly<-reactive(monthly_rows(month(),month_end()))
 output$month_roles<-renderTable({req(identical(input$section,'Monthly'));r<-monthly();if(!nrow(r))return(NULL);{d<-aggregate(r[,c('Target_h','Actual_h','Saved_h','Over_h','Time_value','Units','Gross_extra')],list(Job_id=r$Job_id,Role=r$Role),sum);planned<-plan_period(state(),month(),month_end(),controls$strategy(),controls$protect(),controls$buffer(),controls$cap(),controls$seed(),today());d$Planned_h<-vapply(d$Job_id,function(jid){sum(planned$hours[planned$job_id==jid])},numeric(1));meet<-commitment_events(state(),max(month(),today()),month_end(),'Meeting');d$Scheduled_meeting_left_h<-vapply(d$Job_id,function(jid)sum(meet$end[meet$job_id==jid]-meet$start[meet$job_id==jid]),numeric(1));d$Room_after_reserve_h<-pmax(0,d$Target_h*(1-state()$settings$reserve_pct/100)-d$Actual_h-d$Planned_h-d$Scheduled_meeting_left_h);d}},digits=2,striped=TRUE)
 output$week_matrix<-renderUI({req(identical(input$section,'Monthly'));r<-monthly();if(!nrow(r))return(tags$p(class='empty-hint','Your weekly role balances will appear here.'));weeks<-unique(r$Week);roles<-unique(r$Job_id);tags$div(class='table-responsive',tags$table(class='table balance-matrix',tags$caption('Weekly role balance within the selected month'),tags$thead(tags$tr(tags$th(scope='col','Week beginning'),lapply(roles,function(x)tags$th(scope='col',r$Role[match(x,r$Job_id)])))),tags$tbody(lapply(weeks,function(w)tags$tr(tags$th(scope='row',w),lapply(roles,function(role){z<-r[r$Week==w&r$Job_id==role,,drop=FALSE];if(!nrow(z))return(tags$td('—'));if(z$Pay!='Salary')tags$td(paste(round(z$Actual_h,1),'h ·',round(z$Gross_extra,1),state()$settings$currency,'gross extra'))else if(z$Over_h>0)tags$td(class='balance-negative',paste('Overwork −',round(z$Over_h,1),'h'),tags$small(paste(round(z$Time_value,1),state()$settings$currency)))else if(z$Complete)tags$td(class='balance-positive',paste('Saved +',round(z$Saved_h,1),'h'),tags$small(paste(round(z$Time_value,1),state()$settings$currency)))else tags$td(paste(round(z$Still_needed_h,1),'h still needed'))}))))))})
 output$year_table<-renderTable({req(identical(input$section,'Monthly'));year<-as.integer(input$year %||% format(today(),'%Y'));out<-data.frame();for(m in 1:12){a<-as.Date(sprintf('%04d-%02d-01',year,m));b<-seq(a,by='month',length.out=2)[2]-1;r<-monthly_rows(a,b);note<-state()$reflections;note<-note$note[note$period=='Monthly'&note$date==as.character(a)];out<-rbind(out,data.frame(Month=month.name[m],Recorded_h=sum(r$Actual_h),Saved_h=sum(r$Saved_h),Overwork_h=sum(r$Over_h),Time_value=sum(r$Time_value),Gross_extra=sum(r$Gross_extra),Reflection=if(length(note))note[1]else''))};out},digits=2,striped=TRUE)
 timesheet<-reactive({s<-state();st<-s$settings;d<-timesheet_flags(actual_timesheet(s,month(),month_end()),st$timesheet_start,st$timesheet_end,st$timesheet_lunch_start,st$timesheet_lunch_end);role<-input$timesheet_role %||% '';if(nzchar(role)){d<-d[d$Role_id==role,,drop=FALSE]};d})
 output$timesheet<-renderTable({req(identical(input$section,'Monthly'));d<-timesheet();if(!nrow(d))return(NULL);head(d[,c('Date','Role','Activity','Start','End','Hours','Status','Review')],50)},digits=2,striped=TRUE)
 output$actual_csv<-downloadHandler(filename=function()paste0('worthwhile-recorded-',format(month(),'%Y-%m'),'.csv'),content=function(file)write.csv(timesheet(),file,row.names=FALSE,na='',fileEncoding='UTF-8'))
 output$draft_csv<-downloadHandler(filename=function()paste0('worthwhile-PLANNING-DRAFT-',format(month(),'%Y-%m'),'.csv'),content=function(file){s<-state();st<-s$settings;d<-working_window_draft(s,month(),month_end(),st$timesheet_start,st$timesheet_end,st$timesheet_lunch_start,st$timesheet_lunch_end);role<-input$timesheet_role %||% '';if(nzchar(role)){d<-d[d$Role_id==role|d$Role_id=='',,drop=FALSE]};write.csv(d,file,row.names=FALSE,na='',fileEncoding='UTF-8')})
})
